#[derive(Debug, Clone, Copy, Default)]
pub struct SandboxOptions {
    /// Copy the derived runtime store (`state.db`, its WAL) and the claims store (where `ClaimsStore::path_for` keeps it).
    pub runtime: bool,
    /// Initialise a fresh Git repository with the copied tree committed (for scenarios that observe mutations).
    pub git: bool,
}

pub struct Sandbox {
    pub root: PathBuf,
    pub live_root: PathBuf,
}

impl Sandbox {
    pub fn create(p: &Project, purpose: &str, opts: SandboxOptions) -> Result<Sandbox> {
        let base = p.runtime_dir().join("health").join("sandboxes");
        std::fs::create_dir_all(&base)?;
        let safe: String = purpose
            .chars()
            .map(|c| {
                if c.is_ascii_alphanumeric() || c == '-' {
                    c
                } else {
                    '-'
                }
            })
            .collect();
        let root = base.join(format!("{safe}-{}", crate::util::short_uuid()));
        std::fs::create_dir_all(&root)?;
        // P2-AR-0093 (AR92-C2): record THIS exact, freshly-created, never-reused path as a genuine OS-created
        // sandbox, in the SAME protected machine state `crate::paths::other_live_claim`'s own entries live in --
        // before any project code can run inside it. `is_health_sandbox_root` now requires this record (a path
        // shape alone, `mkdir -p` in a directory of an attacker's own, granted the bootstrap exemption
        // unconditionally; AR92-C2). Best-effort: see `record_sandbox_root`'s own doc for why a failure here costs
        // only tidiness, never security.
        let canon = std::fs::canonicalize(&root).unwrap_or_else(|_| root.clone());
        if let Ok(state_root) = crate::srr::state::resolve_state_root() {
            let _ = crate::paths::record_sandbox_root(&state_root, &canon);
        }
        let sb = Sandbox {
            root: root.clone(),
            live_root: p.root.clone(),
        };
        for (abs, rel) in crate::paths::iter_repo_files(&p.root, false) {
            let dst = root.join(&rel);
            if let Some(d) = dst.parent() {
                std::fs::create_dir_all(d)?;
            }
            copy_if_present(&abs, &dst)?;
        }
        if opts.runtime {
            let rt = root.join(crate::RUNTIME_DIR);
            std::fs::create_dir_all(&rt)?;
            for name in ["state.db", "state.db-wal", "state.db-shm"] {
                copy_if_present(&p.runtime_dir().join(name), &rt.join(name))?;
            }
            // the claims store from where the claims module keeps it (`ClaimsStore::path_for`: the runtime directory,
            // a linked worktree's shared directory, or its BC-P2-31 location), to the same place relative to the
            // sandbox root (the runtime directory when it lives outside the project) — WS-6 IP-R2-12
            let live_claims = crate::memory::claims::ClaimsStore::path_for(p);
            let dst_claims = match live_claims.strip_prefix(&p.root) {
                Ok(rel) => root.join(rel),
                Err(_) => rt.join("claims.db"),
            };
            if let Some(d) = dst_claims.parent() {
                std::fs::create_dir_all(d)?;
            }
            for suffix in ["", "-wal", "-shm"] {
                let with = |x: &Path| PathBuf::from(format!("{}{suffix}", x.display()));
                copy_if_present(&with(&live_claims), &with(&dst_claims))?;
            }
        }
        if opts.git {
            let git = |args: &[&str]| {
                std::process::Command::new("git")
                    .args(args)
                    .current_dir(&root)
                    .env("GIT_AUTHOR_NAME", "gov-health")
                    .env("GIT_AUTHOR_EMAIL", "gov-health@localhost")
                    .env("GIT_COMMITTER_NAME", "gov-health")
                    .env("GIT_COMMITTER_EMAIL", "gov-health@localhost")
                    .output()
            };
            let _ = git(&["init", "-q"]);
            let _ = git(&["add", "-A"]);
            let _ = git(&[
                "commit",
                "-q",
                "--no-verify",
                "-m",
                "health sandbox baseline",
            ]);
        }
        Ok(sb)
    }

    /// Open the sandbox as a project with the caller's session and role.
    pub fn project(&self, like: &Project) -> Project {
        Project::open(&self.root)
            .with_session(Some(like.session_id.clone()), Some(like.role.clone()))
    }
